/* V32 — bouton musique séparé + menu de sélection */
.music-split{display:inline-flex;align-items:stretch;position:relative;flex:0 0 auto;vertical-align:middle}
.music-split #musicBtn{border-top-right-radius:0!important;border-bottom-right-radius:0!important;margin-right:0!important}
.music-split #musicMenuBtn{min-width:28px;padding-left:7px!important;padding-right:7px!important;border-top-left-radius:0!important;border-bottom-left-radius:0!important;margin-left:-1px!important}
.music-choice-menu{display:none;position:fixed;z-index:12000;min-width:285px;max-width:min(360px,calc(100vw - 16px));padding:6px;background:#171612;border:1px solid #6b6252;border-radius:7px;box-shadow:0 12px 30px rgba(0,0,0,.48)}
.music-choice-menu.open{display:block}
.music-choice-menu button{display:block;width:100%;text-align:left;padding:8px 10px;margin:0 0 3px;border:1px solid #474238;border-radius:5px;background:#24221d;color:#f3ead7;font:700 12px Arial,sans-serif;cursor:pointer;white-space:normal}
.music-choice-menu button:last-child{margin-bottom:0}
.music-choice-menu button:hover{background:#343027}
.music-choice-menu button.active{border-color:#d4ab47;background:#3a321f;color:#fff7d1}
.music-choice-menu .music-sub{display:block;font-size:10px;font-weight:400;color:#c9c1b1;margin-top:2px}


/* ===== FINAL MOBILE V34 ===== */
.mobile-day-wrap{display:none;align-items:center;gap:6px;font:700 11px Arial,sans-serif;color:#efe8da;white-space:nowrap}
.mobile-day-wrap select{min-height:38px;border:1px solid #6f695e;background:#292722;color:#fff;padding:6px 28px 6px 9px;border-radius:3px;font:700 12px Arial,sans-serif}
@media(max-width:720px){
  .app{padding:3px}
  .header{gap:5px;margin-bottom:4px}
  .header h1{font-size:16px;line-height:1.08}
  .header p{font-size:9px;line-height:1.2}
  .clockbox{min-width:92px;padding:5px 6px}
  .clock{font-size:20px}
  .clockbox .date{font-size:8px}
  .toolbar.compact-bar{
    position:sticky;top:0;z-index:9500;
    display:grid;grid-template-columns:auto auto minmax(95px,1fr);
    gap:5px;padding:5px;margin-bottom:4px;flex-wrap:nowrap
  }
  .toolbar.compact-bar #play30{grid-column:1;grid-row:1;min-width:44px;padding:5px 8px}
  .toolbar.compact-bar .music-split{grid-column:2;grid-row:1;min-width:0}
  .music-split #musicBtn{max-width:118px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;padding-left:6px!important;padding-right:6px!important;font-size:10px}
  .mobile-day-wrap{display:flex;grid-column:3;grid-row:1;justify-self:stretch}
  .mobile-day-wrap span{display:none}
  .mobile-day-wrap select{width:100%}
  .day-switch{display:none!important}
  .toolbar.compact-bar .compact-time{font-size:10px;align-self:center}
  #timelineStart{grid-column:1;grid-row:2;text-align:left}
  #timeSlider{grid-column:2 / 4;grid-row:2;width:100%!important;min-width:0}
  #timelineEnd{display:none}
  .battle-sticky{top:88px!important}
  .legend{font-size:9px;gap:6px;padding:5px 7px}
  .eventbar{grid-template-columns:54px 1fr;padding:7px 8px;gap:7px}
  .eventbar .etime{font-size:15px}
  .eventbar .etext{font-size:11px}
  .viewport{height:52vh;min-height:370px;max-height:590px;touch-action:none}
  .map-badge{font-size:9px;padding:4px 5px}
  .v17-modal-card{width:min(96vw,720px);max-height:86vh}
  .music-choice-menu{min-width:min(310px,calc(100vw - 12px));max-width:calc(100vw - 12px)}
}
@media(max-width:390px){
  .viewport{min-height:340px}
  .toolbar.compact-bar{grid-template-columns:42px 116px minmax(84px,1fr)}
  .music-split #musicBtn{max-width:91px;font-size:9px}
}
</style>
<style id="final-mobile-v35">
/* V35 : version publique finale — étalonnage embarqué, aucun accès admin. */
#adminPanel,#adminPassModal,#adminBanner{display:none!important}
.viewport{
  touch-action:none!important;
  overscroll-behavior:contain;
  -webkit-user-select:none;
  -webkit-touch-callout:none;
}
.mobile-day-arrow,.mobile-day-select-label{display:none}
@media(max-width:720px){
  html,body{overscroll-behavior-y:none}
  .app{padding:2px!important}
  .toolbar.compact-bar{
    display:grid!important;
    grid-template-columns:48px minmax(0,1fr)!important;
    grid-template-rows:44px 48px 36px!important;
    gap:5px 6px!important;
    padding:5px 6px!important;
    position:sticky!important;top:0!important;z-index:200!important;
  }
  .toolbar.compact-bar #play30{
    grid-column:1!important;grid-row:1!important;width:48px!important;height:44px!important;min-height:44px!important;
    font-size:18px!important;padding:0!important;
  }
  .toolbar.compact-bar .music-split{
    grid-column:2!important;grid-row:1!important;display:grid!important;grid-template-columns:minmax(0,1fr) 44px!important;min-width:0!important;
  }
  .music-split #musicBtn,.music-split #musicMenuBtn{height:44px!important;min-height:44px!important}
  .music-split #musicBtn{max-width:none!important;font-size:11px!important;text-align:left!important}
  .music-split #musicMenuBtn{width:44px!important;font-size:16px!important}
  .mobile-day-wrap{
    display:grid!important;grid-template-columns:48px minmax(0,1fr) 48px!important;align-items:stretch!important;
    grid-column:1 / -1!important;grid-row:2!important;gap:5px!important;width:100%!important;
  }
  .mobile-day-arrow{
    display:block!important;width:48px!important;height:48px!important;min-height:48px!important;padding:0!important;
    font-size:17px!important;background:#38342d!important;color:#fff5df!important;border:1px solid #756b5b!important;
  }
  .mobile-day-select-label{
    display:grid!important;grid-template-columns:44px minmax(0,1fr)!important;align-items:center!important;gap:5px!important;
    background:#211f1b!important;border:1px solid #756b5b!important;border-radius:4px!important;padding:3px 4px 3px 7px!important;
    color:#d7c9ac!important;font:800 10px Arial,sans-serif!important;
  }
  .mobile-day-select-label span{display:block!important;text-align:center!important;letter-spacing:.08em!important}
  .mobile-day-wrap select{
    display:block!important;width:100%!important;height:40px!important;min-height:40px!important;margin:0!important;
    border:0!important;border-left:1px solid #5f584c!important;border-radius:0 3px 3px 0!important;
    background:#2c2924!important;color:#fff!important;padding:6px 34px 6px 10px!important;
    font:900 15px Arial,sans-serif!important;
  }
  #timelineStart{
    grid-column:1!important;grid-row:3!important;align-self:center!important;text-align:center!important;font-size:11px!important;
  }
  #timeSlider{
    grid-column:2!important;grid-row:3!important;align-self:center!important;width:100%!important;min-width:0!important;height:28px!important;margin:0!important;
  }
  #timelineEnd{display:none!important}
  .day-switch{display:none!important}
  .viewport{height:56svh!important;min-height:360px!important;max-height:620px!important}
  .v17-map-hud{top:7px!important;left:7px!important;right:7px!important}
  .v17-map-date{font-size:8px!important;padding:3px 5px!important}
  .v17-map-title{font-size:12px!important;padding:4px 6px!important;max-width:68vw!important}
  .v17-map-time{font-size:22px!important;padding:5px 7px!important}
  .legend{max-height:126px!important;overflow:auto!important;-webkit-overflow-scrolling:touch!important}
  .eventbar{position:relative!important;z-index:10!important}
}
@media(max-width:390px){
  .toolbar.compact-bar{grid-template-columns:46px minmax(0,1fr)!important;padding:4px!important}
  .mobile-day-wrap{grid-template-columns:46px minmax(0,1fr) 46px!important}
  .mobile-day-arrow{width:46px!important}
  .mobile-day-select-label{grid-template-columns:38px minmax(0,1fr)!important;padding-left:4px!important}
  .mobile-day-wrap select{font-size:14px!important}
  .viewport{min-height:345px!important}
}
